const conn = await amqp.connect(url);
const ch = await conn.createChannel();
await ch.prefetch(10);
ch.consume("orders", async (msg) => {          // invoked on delivery
  try {
    await handle(JSON.parse(msg.content));
    ch.ack(msg);
  } catch (e) {
    ch.nack(msg, false, false);              // dead-letter, never throw
  }
}, { noAck: false });
